const request = $input.first().json || {};
const headers = request.headers || {};
const origin = String(headers.origin || '').trim();
const allowedOrigins = new Set(['https://tootooki.github.io']);
if (!allowedOrigins.has(origin)) throw new Error('Origin not allowed');

let payload = request.body ?? request;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch { throw new Error('Invalid request body'); }
}
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) throw new Error('Invalid request body');

const email = String(payload.email || '').trim().toLowerCase();
const topic = String(payload.topic || '').trim();
const message = String(payload.message || '').trim().slice(0, 1000);
const product = String(payload.product || '').trim().slice(0, 100);
const company = String(payload.company || '').trim();
const page = String(payload.page || '').trim();
const startedAt = Number(payload.startedAt || 0);
const now = Date.now();
const topics = { design: 'Find a design', size: 'Size help', updates: 'New drops', chat: 'Chat' };

if (company) throw new Error('Spam rejected');
if (!topics[topic]) throw new Error('Invalid topic');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || email.length > 254) throw new Error('Invalid email');
if (!page.startsWith('https://tootooki.github.io/aofmoka-product-website-v34/')) throw new Error('Invalid page');
if (!Number.isFinite(startedAt) || startedAt <= 0 || now - startedAt < 800 || now - startedAt > 86400000) throw new Error('Invalid timing');

const telegramText = [
  'AOFMOKA WEBSITE CHAT',
  'Topic: ' + topics[topic],
  'Product: ' + (product || 'Not selected'),
  'Message: ' + (message || 'No message'),
  'Email: ' + email,
  'Page: ' + page,
  'Received: ' + new Date(now).toISOString(),
].join('\n');

return [{ json: { email, topic, topicLabel: topics[topic], message, product, page, telegramText } }];
